import openpyxl

path = '/root/output/result.xlsx'
wb = openpyxl.load_workbook(path, data_only=False)
ws = wb['Task']

cells = ['H12','L17','H19','L24','H26','L31','H35','L40','H42','H47','H50','L50']
for addr in cells:
    v = ws[addr].value
    print(f"{addr}: {v}")

# Confirm expected formula presence in full ranges
ranges = [
    ('H12','L17'),('H19','L24'),('H26','L31'),
    ('H35','L40'),('H42','L47'),('H50','L50')
]

def iter_range(a1, a2):
    for row in ws[a1:a2]:
        for cell in row:
            yield cell

missing = []
for a1,a2 in ranges:
    for cell in iter_range(a1,a2):
        if cell.value is None:
            missing.append(cell.coordinate)
        else:
            # for our target, should be a formula string starting with '='
            if isinstance(cell.value,str) and cell.value.startswith('='):
                continue
            missing.append(cell.coordinate)

print('\nNon-formula or missing cells in expected formula ranges:', missing)
wb.close()
